import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { ContentService, PortfolioData } from '../../services/content.service';

@Component({
  selector: 'app-footer',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './footer.component.html'
})
export class FooterComponent implements OnInit {
  content!: PortfolioData;
  currentYear: number = new Date().getFullYear();

  constructor(private contentService: ContentService) {}

  ngOnInit(): void {
    this.contentService.content$.subscribe(data => {
      this.content = data;
    });
  }
}
<footer class="footer">
  <div>
    © {{ currentYear }} <strong>{{ content.personalInfo.name || 'Amit Kumar Maurya' }}</strong>. All rights reserved. Powered by C# ASP.NET Core API & Angular.
  </div>
  <div class="footer-links">
    <a routerLink="/" style="color: #94a3b8; text-decoration: none;">Home</a>
    <a routerLink="/projects" style="color: #94a3b8; text-decoration: none;">Projects</a>
    <a routerLink="/experience" style="color: #94a3b8; text-decoration: none;">Experience</a>
    <a routerLink="/skills" style="color: #94a3b8; text-decoration: none;">Skills</a>
    <a routerLink="/contact" style="color: #94a3b8; text-decoration: none;">Contact</a>
  </div>
</footer>
